pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Synth c;

    function setUp() public {
        c = new Synth();
    }

    function _test(uint256 amount) internal {
        vm.assume(amount != 0);
        uint256 beforeDebt = c.getmapAddress_LPDebt(msg.sender);
        c.mintSynth(msg.sender, amount);
        uint256 afterDebt = c.getmapAddress_LPDebt(msg.sender);
        assertTrue(afterDebt != beforeDebt);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }
}
